mapper.select:
SELECT ROOM.*,TY.TYPE_NAME ,park_name,dormitory_name FROM SMT_DORMITORY_ROOM ROOM

LEFT JOIN SMT_DORMITORY_TYPE TY


ON ROOM.ROOM_TYPE=TY.ID
left join SMT_DORMITORY do on do.id =room.dormitory_id
left join SMT_PARK pa on pa.id=room.park_id


		and ROOM.room_sex =#{query.roomSex }


		and ROOM.park_id =#{query.parkId }


		and ROOM.room_type =#{query.roomType }


		and ROOM.dormitory_id =#{query.dormitoryId }


		and ROOM.floor_id =#{query.floorId  }


		and ROOM.id =#{query.id }


		and ROOM.is_dormitory_room =#{query.isDormitoryRoom  }


		and ROOM.PARK_ID in

			#{item}




ORDER BY ROOM.floor_id,ROOM.id

SELECT ROOM.*,nvl(ROOM.ALIAS_NAME,ROOM.ROOM_NAME) SHOW_NAME,TY.TYPE_NAME ,park_name,dormitory_name FROM SMT_DORMITORY_ROOM ROOM

LEFT JOIN SMT_DORMITORY_TYPE TY


ON ROOM.ROOM_TYPE=TY.ID
left join SMT_DORMITORY do on do.id =room.dormitory_id
left join SMT_PARK pa on pa.id=room.park_id


		and ROOM.room_sex =#{query.roomSex }


		and ROOM.is_count =#{query.isCount }


		and ROOM.park_id =#{query.parkId }


		and ROOM.room_type =#{query.roomType }


		and ROOM.dormitory_id =#{query.dormitoryId }


		and ROOM.floor_id =#{query.floorId  }


		and ROOM.id =#{query.id }


		and ROOM.is_dormitory_room =#{query.isDormitoryRoom  }


		and ROOM.PARK_ID in

			#{item}




ORDER BY ROOM.floor_id,ROOM.id

SELECT M.ROOM_SEX, M.PARK_ID, ( SELECT P.PARK_NAME FROM SMT_PARK P WHERE P.ID = M.PARK_ID ) PARK_NAME, M.DORMITORY_ID, ( SELECT D.DORMITORY_NAME FROM SMT_DORMITORY D WHERE D.ID = M.DORMITORY_ID ) DORMITORY_NAME, M.FLOOR_ID, ( SELECT F.FLOOR_NAME FROM SMT_DORMITORY_FLOOR F WHERE F.ID = M.FLOOR_ID ) FLOOR_NAME, M.TOTAL, (nvl(M.ACTUAL_NUMBER,0) + nvl(M.NO_ROOM_NUMBER,0)) ACTUAL_NUMBER, (M.TOTAL - nvl(M.ACTUAL_NUMBER,0) - nvl(M.NO_ROOM_NUMBER,0) ) SURPLUS FROM ( SELECT T.ROOM_SEX, T.PARK_ID, T.DORMITORY_ID, T.FLOOR_ID, SUM( T.BED_TOTAL ) TOTAL, ( SELECT COUNT( S.STAFF_BADGE ) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM R ON R.ID = S.ROOM_ID WHERE S.PARK_ID = T.PARK_ID AND R.ROOM_SEX = T.ROOM_SEX AND S.FLOOR_ID = T.FLOOR_ID AND R.IS_DORMITORY_ROOM=0 ) ACTUAL_NUMBER, ( SELECT SUM(BED_TOTAL) FROM SMT_DORMITORY_ROOM DR WHERE DR.PARK_ID = T.PARK_ID AND DR.ROOM_SEX = T.ROOM_SEX AND DR.FLOOR_ID = T.FLOOR_ID AND DR.IS_DORMITORY_ROOM=1 ) NO_ROOM_NUMBER FROM SMT_DORMITORY_ROOM T
WHERE T.PARK_ID = #{query.parkId}
and T.DORMITORY_ID in
#{item}
GROUP BY T.PARK_ID, T.DORMITORY_ID, T.FLOOR_ID, T.ROOM_SEX ) M WHERE M.TOTAL != 0 ORDER BY M.DORMITORY_ID, M.FLOOR_ID

SELECT M.ROOM_SEX, M.PARK_ID, ( SELECT P.PARK_NAME FROM SMT_PARK P WHERE P.ID = M.PARK_ID ) PARK_NAME, M.DORMITORY_ID, ( SELECT D.DORMITORY_NAME FROM SMT_DORMITORY D WHERE D.ID = M.DORMITORY_ID ) DORMITORY_NAME, M.FLOOR_ID, ( SELECT F.FLOOR_NAME FROM SMT_DORMITORY_FLOOR F WHERE F.ID = M.FLOOR_ID ) FLOOR_NAME, M.TOTAL, (nvl(M.ACTUAL_NUMBER,0) + nvl(M.NO_ROOM_NUMBER,0)) ACTUAL_NUMBER, ( M.TOTAL - nvl(M.ACTUAL_NUMBER,0) - nvl(M.NO_ROOM_NUMBER,0) ) SURPLUS FROM ( SELECT T.ROOM_SEX, T.PARK_ID, T.DORMITORY_ID, T.FLOOR_ID, SUM( T.BED_TOTAL ) TOTAL, ( SELECT COUNT( S.STAFF_BADGE ) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM R ON R.ID = S.ROOM_ID WHERE S.PARK_ID = T.PARK_ID AND R.ROOM_SEX = T.ROOM_SEX AND S.FLOOR_ID = T.FLOOR_ID AND R.IS_DORMITORY_ROOM=0 ) ACTUAL_NUMBER, ( SELECT SUM(BED_TOTAL) FROM SMT_DORMITORY_ROOM DR WHERE DR.PARK_ID = T.PARK_ID AND DR.ROOM_SEX = T.ROOM_SEX AND DR.FLOOR_ID = T.FLOOR_ID AND DR.IS_DORMITORY_ROOM=1 ) NO_ROOM_NUMBER FROM SMT_DORMITORY_ROOM T
WHERE T.PARK_ID = #{query.parkId}
and T.DORMITORY_ID in
#{item}
GROUP BY T.PARK_ID, T.DORMITORY_ID, T.FLOOR_ID, T.ROOM_SEX) M where M.TOTAL <> 0 and M.TOTAL <> (nvl(M.ACTUAL_NUMBER,0)+nvl(M.NO_ROOM_NUMBER,0)) ORDER BY M.DORMITORY_ID,M.FLOOR_ID

SELECT M.ROOM_SEX, M.PARK_ID, ( SELECT P.PARK_NAME FROM SMT_PARK P WHERE P.ID = M.PARK_ID ) PARK_NAME, M.ROOM_TYPE, ( SELECT Y.TYPE_NAME FROM SMT_DORMITORY_TYPE Y WHERE Y.ID = M.ROOM_TYPE ) TYPE_NAME, M.TOTAL, (nvl(M.ACTUAL_NUMBER,0) + nvl(M.NO_ROOM_NUMBER,0)) ACTUAL_NUMBER, ( M.TOTAL - nvl(M.ACTUAL_NUMBER,0) - nvl(M.NO_ROOM_NUMBER,0) ) SURPLUS FROM ( SELECT T.ROOM_SEX, T.PARK_ID, T.ROOM_TYPE, SUM( T.BED_TOTAL ) TOTAL, ( SELECT COUNT( S.STAFF_BADGE ) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM R ON R.ID = S.ROOM_ID WHERE S.PARK_ID = T.PARK_ID AND R.ROOM_SEX = T.ROOM_SEX AND R.ROOM_TYPE = T.ROOM_TYPE AND R.IS_DORMITORY_ROOM = 0 ) ACTUAL_NUMBER, ( SELECT SUM( BED_TOTAL ) FROM SMT_DORMITORY_ROOM DR WHERE DR.PARK_ID = T.PARK_ID AND DR.ROOM_SEX = T.ROOM_SEX AND DR.ROOM_TYPE = T.ROOM_TYPE AND DR.IS_DORMITORY_ROOM = 1 ) NO_ROOM_NUMBER FROM SMT_DORMITORY_ROOM T
WHERE T.PARK_ID = #{query.parkId}
and T.DORMITORY_ID in
#{item}
GROUP BY T.PARK_ID, T.ROOM_SEX, T.ROOM_TYPE) M order by m.room_type,m.room_sex

SELECT M.PARK_ID, M.PARK_NAME, M.ROOM_TYPE, M.TYPE_NAME, M.MAN_NUMBER, M.WOMAN_NUMBER, M.TOTAL, (M.TOTAL - M.MAN_NUMBER - M.WOMAN_NUMBER) SURPLUS, NVL(M.MAN_TOTAL, 0) MAN_TOTAL, NVL((M.MAN_TOTAL - M.MAN_NUMBER), 0) MAN_SURPLUS, NVL(M.WOMAN_TOTAL, 0) WOMAN_TOTAL, NVL((M.WOMAN_TOTAL - M.WOMAN_NUMBER), 0) WOMAN_SURPLUS FROM (SELECT R.PARK_ID, (SELECT P.PARK_NAME FROM SMT_PARK P WHERE P.ID = R.PARK_ID) PARK_NAME, R.ROOM_TYPE, (SELECT T.TYPE_NAME FROM SMT_DORMITORY_TYPE T WHERE T.ID = R.ROOM_TYPE) TYPE_NAME, (SELECT COUNT(F.ID) FROM SMT_DORMITORY_STAFF F LEFT JOIN SMT_DORMITORY_ROOM O ON O.ID = F.ROOM_ID WHERE F.PARK_ID = R.PARK_ID AND O.ROOM_SEX = 0 AND O.ROOM_TYPE = R.ROOM_TYPE) MAN_NUMBER, (SELECT COUNT(F.ID) FROM SMT_DORMITORY_STAFF F LEFT JOIN SMT_DORMITORY_ROOM O ON O.ID = F.ROOM_ID WHERE F.PARK_ID = R.PARK_ID AND O.ROOM_SEX = 1 AND O.ROOM_TYPE = R.ROOM_TYPE) WOMAN_NUMBER, (select SUM(BED_TOTAL) from SMT_DORMITORY_ROOM RM where RM.PARK_ID=R.PARK_ID AND RM.ROOM_TYPE = R.ROOM_TYPE) TOTAL, (SELECT SUM(DR.BED_TOTAL) FROM SMT_DORMITORY_ROOM DR WHERE DR.PARK_ID = R.PARK_ID AND DR.ROOM_TYPE = R.ROOM_TYPE AND DR.ROOM_SEX = 0) MAN_TOTAL, (SELECT SUM(DR.BED_TOTAL) FROM SMT_DORMITORY_ROOM DR WHERE DR.PARK_ID = R.PARK_ID AND DR.ROOM_TYPE = R.ROOM_TYPE AND DR.ROOM_SEX = 1) WOMAN_TOTAL FROM SMT_DORMITORY_ROOM R LEFT JOIN SMT_DORMITORY_STAFF S ON R.ID = S.ROOM_ID
WHERE R.PARK_ID = #{parkId}
GROUP BY R.PARK_ID, R.ROOM_TYPE) M ORDER BY M.ROOM_TYPE

SELECT S.JCHE_ID,S.JCHE_Name ,S.WELFARE_LEVEL,
(select count(1) from SMT_DORMITORY_STAFF ff LEFT JOIN SMT_STAFF
ss on ff.STAFF_ID=ss."ID" and ss.WELFARE_LEVEL=s.WELFARE_LEVEL
where sex=0 and SS.JCHE_ID=S.JCHE_ID

	AND ff.PARK_ID = #{query.parkId}


	and ff.DORMITORY_ID in

		#{item}


) manNum,

(select count(1) from SMT_DORMITORY_STAFF ff LEFT JOIN SMT_STAFF
ss on ff.STAFF_ID=ss."ID"
where sex=1 and SS.JCHE_ID=S.JCHE_ID and ss.WELFARE_LEVEL=s.WELFARE_LEVEL

	AND ff.PARK_ID = #{query.parkId}


	and ff.DORMITORY_ID in

		#{item}


) womanNum,

(select count(1) from SMT_DORMITORY_STAFF ff LEFT JOIN SMT_STAFF
ss on ff.STAFF_ID=ss."ID"
where sex is null and SS.JCHE_ID=S.JCHE_ID and ss.WELFARE_LEVEL=s.WELFARE_LEVEL

	AND ff.PARK_ID = #{query.parkId}


	and ff.DORMITORY_ID in

		#{item}


) otherNum,

(select count(1) from SMT_DORMITORY_STAFF ff LEFT JOIN SMT_STAFF
ss on ff.STAFF_ID=ss."ID"
where SS.JCHE_ID=S.JCHE_ID and ss.WELFARE_LEVEL=s.WELFARE_LEVEL

	AND ff.PARK_ID = #{query.parkId}


	and ff.DORMITORY_ID in

		#{item}


) total

from SMT_DORMITORY_STAFF F LEFT JOIN SMT_STAFF
S on F.STAFF_ID=S."ID"
WHERE S.JCHE_ID is not null and S.WELFARE_LEVEL is not null

	AND F.PARK_ID = #{query.parkId}


	and F.DORMITORY_ID in

		#{item}


GROUP BY S.JCHE_ID ,s.JCHE_Name,S.WELFARE_LEVEL

SELECT D.ID DORMITORY_ID, D.DORMITORY_NAME, NVL(SUM(R.BED_TOTAL), 0) TOTAL, (SELECT COUNT(S.ID) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM M ON M.ID = S.ROOM_ID WHERE S.DORMITORY_ID = D.ID AND M.ROOM_SEX = 0) MAN_NUMBER, (SELECT COUNT(S.ID) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM M ON M.ID = S.ROOM_ID WHERE S.DORMITORY_ID = D.ID AND M.ROOM_SEX = 1) WOMAN_NUMBER,
(NVL((SELECT COUNT(S.ID) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM M ON M.ID = S.ROOM_ID WHERE S.DORMITORY_ID = D.ID AND M.IS_DORMITORY_ROOM = 0),0) + NVL((SELECT sum(R.BED_TOTAL) FROM SMT_DORMITORY_ROOM R WHERE R.DORMITORY_ID = D.ID AND R.IS_DORMITORY_ROOM = 1 ),0)) totalUseNumber FROM SMT_DORMITORY D LEFT JOIN SMT_DORMITORY_ROOM R ON D.ID = R.DORMITORY_ID
D.PARK_ID=#{parkId}
and D.dormitory_id in
#{item}
GROUP BY D.ID, D.DORMITORY_NAME

SELECT * FROM SMT_DORMITORY_ROOM
WHERE FLOOR_ID=#{floorId}
ORDER BY ROOM_NUM ASC

    select count(1) from SMT_DORMITORY_STAFF
	inner join SMT_STAFF on  STAFF_ID=SMT_STAFF."ID"
	where JCHE_ID=#{jcheId} and SEX=#{sex} AND PARK_ID=#{parkId}

select count(*) from SMT_DORMITORY_ROOM room


		PARK_ID =#{parkId}

	and not EXISTS (select 1 from SMT_DORMITORY_STAFF df where room.ID=df.ROOM_ID)

select dr.PARK_ID,dr.DORMITORY_ID,dr.FLOOR_ID,dr.ID,nvl(dr.ALIAS_NAME,dr.ROOM_NAME) ROOM_NAME,dr.ROOM_TYPE,dr.BED_TOTAL,
dr.ROOM_SEX,(select count(*) from SMT_DORMITORY_STAFF df where df.ROOM_ID=dr.ID) as actCount,dt.TYPE_NAME
from SMT_DORMITORY_ROOM dr
left join SMT_DORMITORY_TYPE dt on dr.ROOM_TYPE=dt.ID


		AND dr.PARK_ID=#{query.parkId}


		AND dr.DORMITORY_ID=#{query.dormitoryId}


		and dr.DORMITORY_ID in

			#{item}



		AND dr.FLOOR_ID=#{query.floorId}


		AND dr.ROOM_TYPE=#{query.roomType}


		AND dr.ROOM_SEX=#{query.sex}


		and dr.PARK_ID in

			#{item}




			AND dr.BED_TOTAL > (select count(*) from SMT_DORMITORY_STAFF df where df.ROOM_ID=dr.ID)


			AND dr.BED_TOTAL=(select count(*) from SMT_DORMITORY_STAFF df where df.ROOM_ID=dr.ID)


			AND 0=(select count(*) from SMT_DORMITORY_STAFF df where df.ROOM_ID=dr.ID)




			AND 0 = (select count(*) from SMT_DORMITORY_STAFF ds left join SMT_STAFF staff on
			ds.STAFF_BADGE=staff.BADGE where ds.ROOM_ID=dr.ID and staff.STATUS=0)


			AND 0 < (select count(*) from SMT_DORMITORY_STAFF ds left join SMT_STAFF staff on
			ds.STAFF_BADGE=staff.BADGE where ds.ROOM_ID=dr.ID and staff.STATUS=0)



ORDER BY dr.ID asc

SELECT
room.ID,
room.ROOM_NAME,
room.ALIAS_NAME,
room.BED_TOTAL,
room.ROOM_TYPE,
room.DORMITORY_ID,
room.ROOM_SEX,
room.FLOOR_ID,
(room.BED_TOTAL-(select count(*) from SMT_DORMITORY_STAFF ds where ds.ROOM_ID=room.ID)) AS freeBedNum
FROM
SMT_DORMITORY_ROOM room


		and room.PARK_ID=#{room.parkId}


		and room.DORMITORY_ID=#{room.dormitoryId}


		and room.FLOOR_ID=#{room.floorId}


		and room.ROOM_TYPE=#{room.roomType}


		and room.ROOM_SEX=#{room.roomSex}


		and room.BED_TOTAL - (select count(*) from SMT_DORMITORY_STAFF ds where ds.ROOM_ID =
		room.ID)=#{freeBedNum}


		and room.ROOM_TYPE in

			#{item}


	order by room.FLOOR_ID asc,room.ROOM_NUM asc

SELECT Q.ROOM_SEX,Q.DORMITORY_DESC,Q.ROOM_TYPE_DESC,Q.ROOM_NUM,Q.TYPE_BED_TOTAL,Q.ROOM_BED_TOTAL,Q.FREE_ROOM_NUM, NVL(Q.ROOM_BED_TOTAL,0) - NVL(Q.AC_ALREADY_USE,0) - NVL(Q.NO_ROOM_USE,0) FREE_BED_NUM , NVL(Q.AC_ALREADY_USE,0) + NVL(Q.NO_ROOM_USE,0) ALREADY_USE, NVL(Q.ROOM_NUM,0) * NVL(Q.TYPE_BED_TOTAL,0) STANDARD_BED_NUM, NVL(Q.ROOM_NUM,0) * NVL(Q.TYPE_BED_TOTAL,0) - NVL(Q.ROOM_BED_TOTAL,0) LOCK_BED_NUM FROM (SELECT B.ROOM_SEX ROOM_SEX,(SELECT DORMITORY_NAME FROM SMT_DORMITORY WHERE ID = B.DORMITORY_ID) DORMITORY_DESC, T.TYPE_NAME ROOM_TYPE_DESC,COUNT(*) ROOM_NUM,T.BED_TOTAL TYPE_BED_TOTAL,SUM(B.BED_TOTAL) ROOM_BED_TOTAL,
(SELECT COUNT(S.STAFF_BADGE ) FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM R ON R.ID = S.ROOM_ID WHERE R.ROOM_SEX = B.ROOM_SEX AND R.ROOM_TYPE = B.ROOM_TYPE AND S.DORMITORY_ID = B.DORMITORY_ID AND R.IS_DORMITORY_ROOM = 0) AC_ALREADY_USE,
(SELECT SUM(BED_TOTAL) FROM SMT_DORMITORY_ROOM R WHERE R.PARK_ID = B.PARK_ID AND R.ROOM_TYPE = B.ROOM_TYPE AND R.ROOM_SEX = B.ROOM_SEX AND R.DORMITORY_ID = B.DORMITORY_ID AND R.IS_DORMITORY_ROOM = 1 ) NO_ROOM_USE,
(SELECT COUNT(*) FROM SMT_DORMITORY_ROOM R WHERE R.DORMITORY_ID = B.DORMITORY_ID AND R.ROOM_TYPE = B.ROOM_TYPE AND R.IS_DORMITORY_ROOM = 0 AND R.ROOM_SEX = B.ROOM_SEX AND R.ID NOT IN (SELECT ROOM_ID FROM SMT_DORMITORY_STAFF S LEFT JOIN SMT_DORMITORY_ROOM r on s.room_id = r.id WHERE S.DORMITORY_ID = B.DORMITORY_ID AND r.ROOM_TYPE = B.ROOM_TYPE AND B.ROOM_SEX = r.ROOM_SEX)) FREE_ROOM_NUM
FROM SMT_DORMITORY_ROOM B LEFT JOIN SMT_DORMITORY_TYPE T ON T.ID = B.ROOM_TYPE
and B.DORMITORY_ID in
#{item}
and B.PARK_ID = #{query.parkId}
and B.ROOM_TYPE in
#{item}
and B.ROOM_SEX = #{query.roomSex}
GROUP BY B.PARK_ID,B.DORMITORY_ID, B.ROOM_TYPE,B.ROOM_SEX, T.TYPE_NAME, T.BED_TOTAL ORDER BY B.DORMITORY_ID ASC ) Q
